59	/**
60	 * The `Actor` for an org already identified by id — used by Route Handlers
61	 * that receive an `orgId` in the payload rather than a slug in the path. The
62	 * session's active org must match, which `assertOrgScope()` enforces.
63	 *
64	 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
65	 * with a single repository lookup rather than by widening that signature —
66	 * the slug is the only handle the session layer knows.
67	 */
68	export async function requireActorFor(orgId: OrgId): Promise<Actor> {
